   objs.append((k,color,set(cells)))
   for p in cells:ids[p]=k
 adj=defaultdict(set); dirs_b=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (conn_between==8 or abs(dr)+abs(dc)==1)]
 for (r,c),a in ids.items():
